reset_sql:
SET autocommit=1;
SET SESSION sql_mode='';
SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ, READ WRITE;

cases.sql:
SET LOCAL TRANSACTION READ ONLY, ISOLATION LEVEL READ COMMITTED;
SET @first=JSON_OBJECT('isolation',@@session.transaction_isolation,'read_only',@@session.transaction_read_only);
SET SESSION TRANSACTION ISOLATION LEVEL SERIALIZABLE, READ WRITE;
